			//   a=[2,1], b=['L','R'] -> first sits at 2, second tries 1, sits at 1; mad=0
			//   a=[2,1], b=['R','L'] -> first sits at 2, second tries 1, sits at 1; mad=0
			//   a=[2,1], b=['R','R'] -> first sits at 2, second tries 1, sits at 1; mad=0
			//   a=[1,1], b=['L','L'] -> first sits at 1, second tries 1, goes right to 2; mad=1
			//   a=[1,1], b=['L','R'] -> first sits at 1, second tries 1, goes right to 2; mad=1
			//   a=[1,1], b=['R','L'] -> first sits at 1, second tries 1, goes right to 2; mad=1
			//   a=[1,1], b=['R','R'] -> first sits at 1, second tries 1, goes right to 2; mad=1
			//   a=[2,2], b=['L','L'] -> first sits at 2, second tries 2, goes left to 1; mad=1
			//   a=[2,2], b=['L','R'] -> first sits at 2, second tries 2, goes left to 1; mad=1
			//   a=[2,2], b=['R','L'] -> first sits at 2, second tries 2, goes left to 1; mad=1
